from lib import *
recs=[
R(2002,"Mangkuk Couscous Kembang Kol",
"Mangkuk ini memiliki rasa yang luar biasa. Rempah-rempah serta tambahan mentimun/peterseli juga memberinya warna yang indah.",
["1-1/2 sendok teh paprika","3/4 sendok teh jintan","1/2 sendok teh lada hitam","1/2 sendok teh cabai cayenne (opsional)","4 cangkir kuntum kembang kol segar","3 sendok makan minyak zaitun, dibagi","1 buah mentimun ukuran sedang","1/2 cangkir peterseli","2 siung bawang putih","2 sendok teh air perasan lemon (lebih baik yang segar)","1/2 cangkir couscous mentah"],
["Panaskan oven terlebih dahulu hingga 400˚F. Campurkan paprika, jintan, lada hitam, dan cabai cayenne. Sisihkan 1 sendok makan untuk couscous.","Letakkan kuntum kembang kol di atas loyang, siram dengan 2 sendok makan minyak zaitun dan taburkan sisa campuran rempah di atas kembang kol. Aduk perlahan agar semua kuntum terbalut.","Tutup loyang dengan longgar menggunakan aluminium foil dan letakkan di rak tengah oven selama 10 menit. Setelah dipanggang 10 menit, buka aluminium foil dan masak 15 menit lagi.","Potong dadu mentimun, cincang peterseli, dan cincang halus bawang putih; lalu campurkan. Siram dengan air perasan lemon dan aduk lagi.","Dalam panci saus kecil, panaskan sisa 1 sendok makan minyak zaitun dan masukkan couscous. Taburkan campuran rempah dan aduk. Tumis hingga couscous sedikit kecokelatan, sekitar 3-5 menit.","Tambahkan 1 cangkir air dan didihkan. Angkat dari api dan diamkan couscous selama 5 menit. Gemburkan dengan garpu, bagi rata ke dalam empat mangkuk.","Keluarkan kembang kol dari oven, bagi rata di atas couscous. Beri campuran mentimun/peterseli di atas setiap mangkuk. Selamat menikmati!"],
["Grain bowl menyenangkan dan fleksibel. Couscous dapat diganti dengan biji-bijian lain seperti nasi atau quinoa.","Cobalah menyesuaikan rempah-rempah dengan selera Anda. Bereksperimenlah dengan bumbu bebas garam untuk menciptakan rasa favorit Anda sendiri.","Bagi pasien DP yang membutuhkan lebih banyak kalium, menambahkan 2 tomat Roma segar akan menjadi tambahan yang bagus untuk resep ini.","Satu kepala kembang kol ukuran sedang menghasilkan sekitar 4 cangkir kuntum.","Satu mentimun ukuran sedang panjangnya sekitar 6 inci.","Satu ikat peterseli menghasilkan 1 cangkir peterseli. Sisa peterseli dari resep ini dapat digunakan dalam hidangan lain.","1/2 cangkir couscous kering sekitar 4 ons, yang menjadi sekitar 1-1/2 cangkir setelah dimasak."],
serving="1-3/4 cangkir"),
R(2003,"Potongan Ayam Asia-Jeruk Nipis yang Renyah",
"Mengapa membeli potongan ayam olahan jika Anda dapat dengan mudah membuat sendiri yang segar? Ahli diet DaVita, Mori, menambahkan sentuhan Asia yang ramah ginjal pada potongan ayam lewat resepnya, Potongan Ayam Asia-Jeruk Nipis yang Renyah.",
["1 pon dada ayam mentah tanpa tulang dan tanpa kulit","1 sendok makan saus tumis Asia","1 sendok makan air jeruk nipis","1 sendok makan madu","1/2 sendok teh lada hitam","1/2 cangkir tepung roti panko"],
["Panaskan oven terlebih dahulu hingga 375°F.","Untuk membuat potongan ayam, potong dada ayam menjadi strip horizontal sepanjang 4 inci dengan ketebalan 1/2 inci.","Dalam mangkuk sedang, campurkan saus tumis, air jeruk nipis, madu, dan lada hitam.","Tambahkan potongan ayam dan aduk hingga terbalut.","Masukkan tepung roti panko ke dalam kantong plastik. Tambahkan ayam dan kocok hingga terbalut rata.","Letakkan ayam dalam loyang yang telah diolesi semprotan antilengket.","Panggang 20-25 menit hingga kecokelatan.","Sajikan dengan nasi, salad, dan buah. Selamat menikmati!"],
["Potong potongan ayam dengan ukuran yang kurang lebih sama agar matang merata. Untuk kemudahan, Anda dapat membeli ayam yang sudah dipotong menjadi strip. Biasanya diberi label chicken fingers, chicken strips, atau chicken tenders.","Tepung roti panko adalah tepung roti ala Jepang yang dibuat dari roti putih tanpa kulit dan diproses menjadi serpihan, bukan remah. Panko menyerap lebih sedikit lemak dan lebih rendah natrium dibandingkan tepung roti biasa.","Bandingkan merek saus tumis dan pilih yang natriumnya paling rendah. Anda dapat menggantinya dengan saus teriyaki jika saus tumis tidak tersedia, tetapi kandungan natriumnya mungkin lebih tinggi.","Sesuaikan porsi jika Anda membutuhkan protein lebih banyak atau lebih sedikit."],
serving="6 potong ayam"),
R(2006,"Ayam Pedas ala New Delhi",
"Resep ayam yang terinspirasi dari New Delhi ini adalah hidangan ramah ginjal dengan sedikit sensasi pedas. Nikmati Ayam Pedas ala New Delhi pada waktu makan Anda berikutnya.",
["1/2 cangkir bawang bombai, dicincang halus","1 sendok makan pasta bawang putih","1 sendok makan pasta jahe","3 sendok makan krim asam","1/2 cangkir air perasan lemon","2 sendok teh bubuk kunyit","1 sendok teh bubuk cabai merah","1 sendok teh bubuk jintan","1 sendok teh lada hitam bubuk","1 sendok teh cengkih bubuk","1 sendok teh kayu manis","1 pon dada ayam tanpa tulang dan tanpa kulit"],
["Untuk menyiapkan marinasi, haluskan semua bahan kecuali ayam hingga menjadi pasta yang halus.","Cuci ayam dan keringkan dengan tisu dapur. Letakkan dalam loyang kaca yang dangkal. Tuang pasta marinasi ke atas ayam, balurkan pada setiap potong dengan baik. Simpan di lemari es selama 2 jam untuk dimarinasi. Balik sekali atau dua kali.","Panaskan oven terlebih dahulu hingga 350°F. Letakkan ayam dalam loyang dan panggang selama 20-25 menit.","Didihkan sisa marinasi lalu gunakan untuk mengolesi ayam."],
["Belilah 4 dada ayam, masing-masing 4 ons.","Ini resep yang sangat cocok untuk dipanggang di atas gril."],
serving="3-1/2 ons dada ayam"),
R(2007,"Ayam dan Sayuran Panggang Rosemary",
"Hanya beberapa saat setelah Anda menutup pintu oven, Anda akan tahu hidangan istimewa menanti saat aroma lembut rosemary memenuhi udara! Resep Ayam dan Sayuran Panggang Rosemary dari ahli diet ginjal DaVita, Sarah dari California, hampir menjadi hidangan lengkap tersendiri, karena sayuran panggang menambah rasa dan nutrisi. Dan karena resep ini telah disesuaikan untuk mereka yang menjalani diet ginjal, semua orang dapat menikmati hidangan lezat dan mengenyangkan ini.",
["2 buah zukini ukuran sedang","1 buah wortel ukuran sedang","1/2 buah paprika","1/2 buah bawang merah besar","8 siung bawang putih","1 sendok makan minyak zaitun","1/4 sendok teh lada bubuk","4 dada ayam, dengan tulang","1 sendok makan rosemary kering"],
["Panaskan oven terlebih dahulu hingga 375° F.","Iris zukini setebal 1/2″; iris wortel dan paprika setebal 1/4″; potong bawang menjadi irisan bulan 1/2″; memarkan siung bawang putih.","Campurkan zukini, wortel, paprika, bawang, bawang putih, dan minyak dalam loyang panggang 13″ x 9″. Bumbui campuran dengan 1/2 sendok teh lada hitam dan aduk hingga terbalut. Panggang hingga sayuran hangat merata, sekitar 10 menit.","Sementara sayuran dipanggang, angkat kulit dari dada ayam dan gosok dagingnya dengan lada hitam dan rosemary yang diremas. Kembalikan kulitnya, lalu bumbui ayam di seluruh permukaan dengan tambahan lada dan rosemary, sesuai selera.","Keluarkan loyang dari oven, dan letakkan ayam, dengan sisi kulit menghadap ke atas, di atas sayuran. Masukkan kembali ke oven dan lanjutkan memanggang hingga ayam matang sepenuhnya dan sayuran empuk (sekitar 35 menit)."],
["Jika menginginkan rasa tambahan, Anda juga dapat menggunakan campuran bumbu herba Mrs. Dash® atau bumbu unggas berempah untuk melumuri ayam.","Cocok disajikan dengan nasi atau roti.","Ayam harus dimasak hingga matang sepenuhnya, yaitu ketika cairannya bening saat dipotong atau mencapai suhu 165° F.","Jika Anda menjalani diet lebih rendah protein, kurangi porsi ayam agar sesuai dengan rencana makan Anda."],
serving="1 potong ayam dan 3/4 cangkir sayuran"),
R(2010,"Patty Hamburger",
"Nicole dari Nebraska, ahli diet DaVita, menemukan hidangan klasik favorit yang menenangkan dan menjadikannya ramah diet ginjal tanpa mengorbankan rasa. Patty Hamburger yang dibumbui dengan lezat ini pasti menjadi favorit.",
["2 sendok makan bawang bombai","1 siung bawang putih","1 pon daging sapi giling tanpa lemak","2 putih telur","1/2 cangkir kaldu sapi rendah natrium","10 biskuit soda rendah natrium","1 sendok teh mustard kering","1/2 sendok makan peterseli kering","1/4 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 425° F.","Cincang bawang bombai dan cincang halus siung bawang putih. Hancurkan biskuit dan ukur 1/2 cangkir.","Campurkan semua bahan dalam mangkuk besar.","Bentuk campuran daging menjadi 6 patty hamburger.","Letakkan patty dalam loyang.","Panggang tanpa ditutup selama 20 menit."],
["Untuk hidangan lengkap, tambahkan roti hamburger kecil, seiris bawang, selada, dan 1 sendok teh saus tomat.","Resep ini juga dapat digunakan untuk membuat meatloaf.","Untuk diet tinggi protein, buat 4 patty agar ukuran patty menjadi 3 ons setelah dimasak. Protein meningkat menjadi 27 gram per porsi.","Sebagai pengganti dipanggang di oven, Anda dapat memanggang patty di atas barbekyu, dibalik sekali hingga matang sempurna."],
serving="1 patty matang 2 ons"),
R(2011,"Tart Keju",
"Hidangan penutup yang lezat dan camilan manis adalah cara yang bagus bagi pasien dialisis untuk mendapatkan kalori tambahan saat tidak berselera makan. Resep Tart Keju dari ahli diet ginjal, Arlene dari California, ini menampilkan isian keju yang creamy dengan topping isian pai buah rendah kalium pilihan Anda.",
["8 ons krim keju","2 butir telur","3/4 cangkir gula","2 sendok teh ekstrak vanila","2 lusin alas kertas cupcake","2 lusin wafer vanila","1-1/2 cangkir isian pai apel"],
["Keluarkan krim keju agar melunak selama 1 jam sebelum membuat tart.","Panaskan oven terlebih dahulu hingga 350° F.","Campurkan krim keju, telur, gula, dan ekstrak vanila dalam mangkuk dan kocok hingga halus.","Letakkan alas kertas cupcake dalam loyang muffin. Taruh satu wafer vanila di setiap alas kertas.","Tuang campuran krim keju di atas wafer vanila, hingga sekitar 3/4 penuh.","Panggang selama 10 menit. Keluarkan tart dari oven dan dinginkan di lemari es.","Tepat sebelum disajikan, beri topping setiap tart dengan 1-1/2 sendok makan isian pai buah."],
["Isian pai buah yang disarankan meliputi ceri, blueberry, apel, atau stroberi."],
serving="1 tart"),
R(2013,"Tumis Sayuran",
"Cobalah resep ramah ginjal Tumis Sayuran untuk beragam sayuran sehat rendah kalium yang berwarna-warni.",
["1 buah paprika hijau ukuran sedang","1 buah paprika merah ukuran sedang","3/4 cangkir jamur segar iris","1/2 buah tomat ukuran sedang","1 batang seledri ukuran sedang","1/2 buah bawang bombai kecil","1 siung bawang putih","2 sendok makan minyak canola","1/2 sendok teh gula","1/2 sendok teh oregano kering","1/4 sendok teh garam","1/4 sendok teh lada segar giling","1 sendok teh cuka anggur merah","1/2 cangkir water chestnut iris kalengan"],
["Iris paprika hijau dan merah serta seledri. Cincang bawang bombai. Memarkan siung bawang putih. Potong setengah tomat menjadi 4 bagian.","Dalam wajan besar, panaskan minyak. Masukkan paprika hijau, paprika merah, jamur, seledri, bawang bombai, bawang putih, gula, oregano, garam, dan lada.","Tumis dengan api sedang-besar hingga paprika renyah namun empuk.","Tambahkan cuka, tomat, dan water chestnut yang telah ditiriskan. Masak hingga panas merata."],
["Satu sendok makan kecap asin rendah natrium dapat digunakan sebagai pengganti garam.","Pilih tomat yang keras. Dapat diganti dengan 4 hingga 6 tomat ceri atau tomat anggur, dibelah dua."],
serving="3/4 cangkir per porsi"),
R(2016,"Meat Loaf Microwave dalam Mug",
"Tak perlu mencari lagi hidangan utama satu wadah yang cepat dan super mudah dibuat. Ahli diet DaVita, Maryann, telah menciptakan Meat Loaf Microwave dalam Mug.",
["2 sendok makan susu rendah lemak 1%","2 sendok teh saus tomat","2 sendok makan oat instan","1 sendok teh bubuk bawang bombai","1/4 pon daging sapi giling tanpa lemak"],
["Semprot mug 12 ons yang aman untuk microwave dengan semprotan masak.","Dalam mangkuk, campurkan susu (atau pengganti susu), saus tomat, oat, dan bubuk bawang bombai.","Remukkan daging sapi di atas campuran dan aduk rata. Padatkan ke dalam mug.","Tutup dan microwave dengan daya TINGGI selama 3 menit atau hingga daging tidak lagi berwarna merah muda."],
["Bandingkan merek dan pilih saus tomat dengan natrium terendah.","Carilah daging sapi giling dengan kandungan lemak minimal 7% untuk resep ini. Daging kalkun giling merupakan pengganti yang baik.","Gunakan pengganti susu favorit Anda sebagai pengganti susu jika diinginkan.","Jika Anda menjalani diet lebih rendah protein, sesuaikan jumlah daging sapi giling agar sesuai dengan rencana makan Anda."],
serving="1 mug"),
R(2017,"Salad Mentimun Marinasi",
"Sebagai pengganti acar mentimun, nikmati rasa dan aroma mentimun segar. Salad Mentimun Marinasi karya ahli diet DaVita, Eileen, adalah tambahan rendah natrium yang bagus untuk hidangan apa pun, atau menjadi camilan rendah kalori yang menyegarkan.",
["2 buah mentimun besar","1/2 cangkir bawang merah","1/4 sendok teh lada hitam","1 cangkir cuka","1 cangkir air keran dingin","2 sendok makan gula"],
["Kupas dan potong dadu mentimun; cincang bawang.","Dalam mangkuk sedang, campurkan sayuran dan lada hitam.","Dalam mangkuk terpisah, campurkan cuka dan air dengan gula lalu diamkan selama 15 menit.","Tuang campuran cuka ke atas campuran mentimun dan simpan di lemari es setidaknya 3 jam sebelum disajikan."],
["Gunakan pengganti gula untuk mengurangi karbohidrat menjadi 5 gram.","Salad Mentimun Marinasi sangat cocok dengan hidangan ayam atau salad tuna atau telur. Ini adalah pendamping yang menyegarkan untuk hidangan apa pun."],
serving="1/2 cangkir"),
R(2018,"Aneka Paprika Pedas",
"Tambahkan sedikit rasa pedas pada hidup dan diet Anda. Ahli diet ginjal DaVita, Sindu dari California, menawarkan resepnya yang berwarna-warni dan ramah ginjal, Aneka Paprika Pedas.",
["2 sendok makan minyak canola","1 cangkir bawang merah","1 cangkir paprika oranye","1 cangkir paprika hijau","1 cangkir paprika merah","1/2 sendok teh lada hitam","1 sendok makan bubuk kari pedas","1/4 sendok teh garam"],
["Iris tipis bawang merah. Potong dadu paprika.","Panaskan minyak dalam wajan ukuran sedang, masukkan bawang merah dan masak selama 5 menit.","Bumbui bawang dengan lada hitam dan bubuk kari lalu masak 5 menit lagi.","Masukkan paprika dan masak selama 15 menit, aduk beberapa kali.","Bumbui dengan garam dan matikan api. Diamkan sekitar 5 menit.","Sajikan panas dengan tortilla tepung atau di atas nasi."],
["Bubuk kari Bolst’s® adalah merek favorit Sindu untuk resep ini.","Satu paprika ukuran sedang menghasilkan sekitar 1 cangkir. Satu bawang merah ukuran sedang menghasilkan sekitar 1 cangkir.","Apakah Anda membutuhkan lebih banyak protein dalam diet Anda? Sebelum disajikan, aduk 3 sendok takar bubuk protein atau tambahkan makanan protein favorit Anda untuk menjadikan ini hidangan yang diperkaya protein."],
serving="1/2 cangkir"),
R(2019,"Kue Kering Krim Keju Mint Tanpa Panggang",
"Enam bahan sederhana, mixer, dan lemari es adalah semua yang Anda butuhkan untuk membuat Kue Kering Krim Keju Mint Tanpa Panggang.",
["4 ons krim keju","1/8 sendok teh ekstrak mint","4 cangkir gula halus","1 sendok makan susu","1/4 cangkir taburan meses musim liburan","1/3 cangkir gula pasir"],
["Keluarkan krim keju agar melunak.","Dengan mixer kecepatan rendah, campurkan krim keju dan ekstrak mint.","Campurkan 2 cangkir gula halus hingga halus","Tambahkan 1 cangkir gula halus lagi dan 2 sendok makan taburan meses. Aduk dengan kecepatan rendah hingga tercampur","Lipat sisa 1 cangkir gula halus hingga tercampur.","Dalam mangkuk terpisah, campurkan gula pasir dan sisa taburan meses musim liburan.","Bentuk adonan menjadi bola berukuran 3/4 inci dan gulingkan dalam campuran gula dan taburan meses.","Letakkan bola-bola adonan di atas loyang dan simpan di lemari es selama 30 menit.","Keluarkan dari lemari es dan pipihkan bola-bola perlahan dengan garpu.","Simpan dalam wadah kedap udara di lemari es hingga siap disajikan."],
["Gunakan gula pasir berwarna agar lebih berwarna-warni.","Tingkatkan ekstrak mint menjadi 1/4 sendok teh untuk rasa mint yang lebih kuat.","Cobalah taburan cokelat untuk rasa mint-cokelat."],
serving="1 kue kering"),
R(2020,"Shepherd’s Pie Mudah",
"Shepherd’s Pie Mudah memadukan semua yang lezat — kentang tumbuk, daging sapi giling gurih, dan sayuran manis — dalam satu hidangan panas yang nikmat. Juhi, ahli diet DaVita dari California, tumbuh besar di Inggris dan telah menciptakan resep ramah ginjal yang mudah dibuat dari hidangan tradisional Inggris ini yang akan disukai orang Amerika.",
["1 buah bawang bombai ukuran sedang","3/4 cangkir wortel","3 siung bawang putih","2 buah kentang ukuran sedang","4 sendok makan mentega","1-1/2 pon daging sapi giling tanpa lemak (7% lemak)","1/2 sendok teh lada hitam","2 sendok teh saus Worcestershire","1/3 cangkir saus tomat","3/4 cangkir kacang polong hijau beku","1 cangkir susu rendah lemak 1%","1/2 cangkir saus kental cokelat (brown gravy)"],
["Cincang bawang bombai dan wortel. Cincang halus siung bawang putih. Kupas kentang dan potong menjadi potongan 1/2 inci. Rebus dalam panci besar berisi air selama 5 menit. Buang air, ganti dengan air baru dan rebus lagi hingga kentang empuk; tiriskan.","Selagi kentang dimasak, lelehkan 2 sendok makan mentega dalam wajan besar. Dengan api sedang, tumis bawang bombai dan bawang putih hingga empuk (10 menit).","Tambahkan daging sapi giling dan tumis hingga tidak lagi berwarna merah muda.","Tambahkan lada, saus Worcestershire, saus tomat, dan sayuran. Didihkan perlahan dengan api kecil, tanpa ditutup, selama 10 menit.","Panaskan oven terlebih dahulu hingga 400° F.","Tumbuk kentang dalam mangkuk dengan 2 sendok makan mentega. Aduk susu agar kentang bertekstur creamy. Tambahkan lada secukupnya.","Ratakan daging sapi dalam loyang. Tutup merata dengan kentang tumbuk. Gunakan garpu untuk membuat pola.","Panggang selama 30 menit hingga menggelembung. Untuk mencokelatkan bagian atas, panggang dengan broiler selama 2 menit jika diinginkan.","Sajikan 1 sendok makan saus kental di atas setiap porsi."],
["Merebus kentang dua kali dalam panci besar berisi air mengurangi kandungan kalium. Kupas dan potong kentang menjadi potongan kecil, tutup dengan air dan rebus 5 menit. Ganti dengan air baru dan masak hingga kekenyalan yang diinginkan. Buang air rebusannya.","Bekukan porsi tambahan untuk makanan cepat saji di lain waktu.","Analisis nutrisi mencakup saus kental dari campuran kering. Buat saus kental buatan sendiri rendah natrium untuk mengurangi kandungan natrium."],
serving="1/8 pai"),
R(2024,"Salad Bayam Stroberi",
"Pilihlah hidangan yang sehat dan lezat dengan Salad Bayam Stroberi yang ramah ginjal.",
["3 cangkir bayam segar","1 cangkir stroberi segar","1 sendok makan cuka","1 sendok makan air perasan lemon","2 sendok makan madu","1/8 sendok teh mustard kering","3 sendok makan minyak nabati"],
["Cuci dan keringkan daun bayam. Sobek menjadi potongan seukuran gigitan dan letakkan dalam mangkuk. Iris tipis stroberi.","Letakkan irisan stroberi di atas bayam.","Campurkan cuka, air perasan lemon, madu, mustard kering, dan minyak.","Tuang dressing ke atas bayam dan stroberi. Aduk rata dan sajikan segera."],
["Satu porsi bayam mentah lebih rendah kalium daripada satu porsi bayam matang. Ini karena bayam mentah kehilangan strukturnya dan “menyusut” saat dimasak. Jauh lebih banyak daun bayam matang yang dibutuhkan untuk satu porsi. Sebagai perbandingan: 1/2 cangkir bayam segar matang beratnya 3 ons dan mengandung 419 mg kalium, sedangkan 1/2 cangkir bayam segar mentah beratnya 1 ons dan mengandung 156 mg kalium.","Satu kemasan bayam seberat 6 ons yang sudah dicuci mengandung 3 cangkir."],
serving="2/3 cangkir"),
R(2029,"Dressing Salad Dijon Mudah",
"Dressing Salad Dijon Mudah adalah resep ramah ginjal yang menyegarkan untuk melengkapi salad Anda.",
["2 sendok makan mustard Dijon","1/4 cangkir minyak zaitun","1/3 cangkir cuka beras tanpa bumbu","1 sendok makan gula merah","1 sendok teh campuran bumbu herba Mrs. Dash®"],
["Campurkan bahan-bahan dalam toples atau mangkuk kecil dan aduk hingga tercampur.","Dinginkan hingga siap disajikan."],
["Carilah merek mustard dengan natrium terendah.","Dressing tahan hingga 2 minggu di lemari es.","Cobalah dressing ini sebagai marinasi atau topping daging."]),
R(2030,"Ikan Putih Goreng ala Korea (Saeng-seon-Jeon)",
"Resep ramah ginjal hidangan ikan Korea, Ikan Putih Goreng ala Korea (Saeng-seon-Jeon), ini dimulai dengan ikan putih yang empuk berlapis, ditambah cuka beras yang menyegarkan dan kecap asin rendah natrium, lalu digoreng hingga sempurna.",
["1 sendok makan cuka beras tanpa bumbu","1 sendok teh kecap asin rendah natrium","1 pon fillet ikan putih","3 sendok makan tepung terigu putih serbaguna","1/2 sendok teh lada hitam","2 butir telur besar","3 sendok makan minyak wijen"],
["Campurkan cuka dengan kecap asin dalam mangkuk kecil. Sisihkan hingga ikan siap disajikan.","Bilas ikan dan keringkan dengan tisu dapur. Potong setiap fillet ikan menjadi potongan 1-1/2″.","Masukkan tepung dan lada ke dalam kantong berzip. Tambahkan ikan, tutup rapat dan kocok hingga terbalut.","Dalam mangkuk kecil, kocok telur ringan.","Panaskan minyak wijen dalam wajan besar.","Celupkan setiap potong ikan berlapis tepung ke dalam telur kocok hingga terbalut. Letakkan dalam minyak panas dan goreng hingga cokelat keemasan, balik sekali.","Bagi menjadi 4 porsi dan sajikan panas. Percikkan 1 sendok teh campuran cuka-kecap asin pada setiap porsi."],
["Jika ikan putih tidak tersedia, ganti dengan ikan lele, kod, orange roughy, atau ikan nila.","Tiriskan ikan yang telah dimasak di atas tisu dapur untuk menyerap kelebihan minyak.","Ukur campuran cuka-kecap asin untuk membantu menjaga kandungan natrium tetap rendah.","Untuk diet rendah protein, kurangi porsi agar sesuai dengan rencana makan Anda atau konsultasikan dengan ahli diet Anda."],
serving="1/4 resep, sekitar 4 ons"),
]
save(4,recs)
